export interface ConnectorConfig {
  /** Mailchimp API key (from MAILCHIMP_API_KEY env var) */
  mailchimpApiKey: string;
  /** Mailchimp list ID (audience ID) */
  listId: string;
  /** Tag name to add (default: "Refunded") */
  tagName?: string;
  /** Injected fetch for testing */
  fetch?: typeof fetch;
}

export interface StripeChargeRefundedPayload {
  id: string;
  object: 'event';
  type: 'charge.refunded';
  data: {
    object: {
      id: string;
      customer: string;
      amount: number;
      currency: string;
      refunded: boolean;
    };
  };
}

export interface HandleResult {
  /** Whether the tag was added (false if skipped) */
  tagAdded: boolean;
  /** Stripe charge ID used as idempotency key and subscriber hash */
  chargeId: string;
  /** Subscriber hash used in Mailchimp API (equals chargeId per field mapping) */
  subscriberHash: string;
  /** Tag name that was added or skipped */
  tagName: string;
  /** True if tag already existed and POST was skipped */
  skipped: boolean;
}

async function fetchWithAuth(
  fetchImpl: typeof fetch,
  url: string,
  options: RequestInit,
  apiKey: string
): Promise<Response> {
  const headers = new Headers(options.headers);
  headers.set('Authorization', `Bearer ${apiKey}`);
  return fetchImpl(url, { ...options, headers });
}

export async function handle(
  payload: StripeChargeRefundedPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  // Validate required payload fields
  if (!payload.data?.object?.id) {
    throw new Error('Missing required field: data.object.id (charge ID)');
  }
  if (!payload.data?.object?.customer) {
    throw new Error('Missing required field: data.object.customer (customer ID)');
  }
  if (!config.mailchimpApiKey) {
    throw new Error('Missing required config: mailchimpApiKey');
  }
  if (!config.listId) {
    throw new Error('Missing required config: listId');
  }

  const chargeId = payload.data.object.id;
  const subscriberHash = chargeId; // Per fieldMapping: charge.id -> subscriber.id
  const tagName = config.tagName ?? 'Refunded';
  const baseUrl = `https://api.mailchimp.com/3.0/lists/${config.listId}/members/${subscriberHash}/tags`;

  const fetchImpl = config.fetch ?? globalThis.fetch;

  // GET existing tags to check for duplicate
  const getResponse = await fetchWithAuth(fetchImpl, baseUrl, { method: 'GET' }, config.mailchimpApiKey);
  if (!getResponse.ok) {
    throw new Error(`GET ${baseUrl} failed with status ${getResponse.status}`);
  }
  const getData = await getResponse.json() as { tags?: Array<{ name: string; status: string }> };
  const existingTags = getData.tags ?? [];
  const tagExists = existingTags.some(tag => tag.name === tagName && tag.status === 'active');

  if (tagExists) {
    return {
      tagAdded: false,
      chargeId,
      subscriberHash,
      tagName,
      skipped: true,
    };
  }

  // POST to add tag with Idempotency-Key
  const postBody = JSON.stringify({
    tags: [{ name: tagName, status: 'active' }],
  });
  const postHeaders = new Headers();
  postHeaders.set('Idempotency-Key', chargeId);
  postHeaders.set('Content-Type', 'application/json');

  const postResponse = await fetchWithAuth(fetchImpl, baseUrl, {
    method: 'POST',
    body: postBody,
    headers: postHeaders,
  }, config.mailchimpApiKey);

  if (!postResponse.ok) {
    throw new Error(`POST ${baseUrl} failed with status ${postResponse.status}`);
  }

  return {
    tagAdded: true,
    chargeId,
    subscriberHash,
    tagName,
    skipped: false,
  };
}

