import { handle, ConnectorConfig, StripeChargeRefundedPayload, HandleResult } from './connector';
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      mailchimpApiKey: 'test-api-key',
      listId: 'test-list-id',
      tagName: 'Refunded',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as StripeChargeRefundedPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.tagAdded).toBe(false);
    expect(result.skipped).toBe(true);
    expect(result.chargeId).toBe('ch_1234567890');
    expect(result.subscriberHash).toBe('ch_1234567890');
    expect(result.tagName).toBe('Refunded');
  });
});

