  it('adds tag when not present (happy path)', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET') {
        return jsonResponse({ tags: [] });
      }
      if (req.method === 'POST') {
        expect(req.json).toEqual({ tags: [{ name: 'Refunded', status: 'active' }] });
        expect(req.headers.get('idempotency-key')).toBe('ch_1234567890');
        return jsonResponse({}, 200);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const config: ConnectorConfig = {
      mailchimpApiKey: 'test-key',
      listId: 'list-123',
      fetch,
    };
    const payload: StripeChargeRefundedPayload = {
      id: 'evt_1',
      object: 'event',
      type: 'charge.refunded',
      data: {
        object: {
          id: 'ch_1234567890',
          customer: 'cus_abc',
          amount: 1000,
          currency: 'usd',
          refunded: true,
        },
      },
    };

    const result = await handle(payload, config);
    expect(result.tagAdded).toBe(true);
    expect(result.skipped).toBe(false);
    expect(calls.length).toBe(2);
    expect(calls[0].method).toBe('GET');
    expect(calls[1].method).toBe('POST');
  });

  it('sends Authorization header with Bearer token', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      const auth = req.headers.get('authorization');
      expect(auth).toBe('Bearer test-key');
      if (req.method === 'GET') return jsonResponse({ tags: [] });
      return jsonResponse({}, 200);
    });

    const config: ConnectorConfig = {
      mailchimpApiKey: 'test-key',
      listId: 'list-123',
      fetch,
    };
    const payload: StripeChargeRefundedPayload = {
      id: 'evt_1',
      object: 'event',
      type: 'charge.refunded',
      data: {
        object: {
          id: 'ch_1',
          customer: 'cus_1',
          amount: 100,
          currency: 'usd',
          refunded: true,
        },
      },
    };

    await handle(payload, config);
    expect(calls.length).toBeGreaterThan(0);
