        return jsonResponse({ tags: [] });
      }
      if (req.method === 'POST') {
        expect(req.url).toContain('/members/ch_999/tags');
        expect(req.headers.get('idempotency-key')).toBe('ch_999');
        return jsonResponse({}, 200);
