    const payload: StripeChargeRefundedPayload = {
      id: 'evt_1',
      object: 'event',
      type: 'charge.refunded',
      data: {
        object: {
          id: 'ch_999',
          customer: 'cus_1',
          amount: 100,
          currency: 'usd',
          refunded: true,
