      object: 'event' as const,
      type: 'charge.refunded' as const,
      data: { object: { id: 'ch_1', amount: 100, currency: 'usd', refunded: true } },
    } as unknown as StripeChargeRefundedPayload;

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: data.object.customer');
