    const { fetch } = fakeFetch(() => jsonResponse({ error: 'not found' }, 404));
    const config: ConnectorConfig = { mailchimpApiKey: 'key', listId: 'list', fetch };
    const payload: StripeChargeRefundedPayload = {
      id: 'evt_1',
      object: 'event',
      type: 'charge.refunded',
      data: { object: { id: 'ch_1', customer: 'cus_1', amount: 100, currency: 'usd', refunded: true } },
