  it('throws on non-2xx POST response', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.method === 'GET') return jsonResponse({ tags: [] });
      return jsonResponse({ error: 'conflict' }, 409);
    });
    const config: ConnectorConfig = { mailchimpApiKey: 'key', listId: 'list', fetch };
    const payload: StripeChargeRefundedPayload = {
      id: 'evt_1',
      object: 'event',
      type: 'charge.refunded',
      data: { object: { id: 'ch_1', customer: 'cus_1', amount: 100, currency: 'usd', refunded: true } },
    };

    await expect(handle(payload, config)).rejects.toThrow('POST https://api.mailchimp.com/3.0/lists/list/members/ch_1/tags failed with status 409');
  });

  it('uses custom tagName from config', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET') return jsonResponse({ tags: [] });
      expect(req.json).toEqual({ tags: [{ name: 'CustomTag', status: 'active' }] });
