    });

    const config: ConnectorConfig = {
      mailchimpApiKey: 'key',
      listId: 'list',
      tagName: 'CustomTag',
      fetch,
    };
    const payload: StripeChargeRefundedPayload = {
      id: 'evt_1',
      object: 'event',
      type: 'charge.refunded',
      data: { object: { id: 'ch_1', customer: 'cus_1', amount: 100, currency: 'usd', refunded: true } },
    };

    const result = await handle(payload, config);
    expect(result.tagName).toBe('CustomTag');
    expect(result.tagAdded).toBe(true);
  });
});

# Stripe Charge Refunded → Mailchimp Tag Connector

Adds a tag to a Mailchimp subscriber when a Stripe `charge.refunded` webhook is received. The connector checks existing tags first and skips the addition if the tag is already present, using the Stripe charge ID as an idempotency key to prevent duplicates.

## What it does

1. Receives a Stripe `charge.refunded` webhook payload
2. Extracts the charge ID (`data.object.id`)
3. Queries Mailchimp for the subscriber's current tags (subscriber hash = charge ID)
4. If the configured tag (default: "Refunded") is already active, exits without calling POST
5. Otherwise, POSTs the tag to Mailchimp with `Idempotency-Key: <charge-id>` header

## Configuration

| Config Property | Environment Variable | Required | Description |
|-----------------|---------------------|----------|-------------|
| `mailchimpApiKey` | `MAILCHIMP_API_KEY` | Yes | Mailchimp API key (Bearer token) |
| `listId` | — | Yes | Mailchimp list (audience) ID |
| `tagName` | — | No | Tag name to add (default: "Refunded") |

## Usage Example

```typescript
import { handle, ConnectorConfig } from './connector';

const config: ConnectorConfig = {
  mailchimpApiKey: process.env.MAILCHIMP_API_KEY!,
  listId: 'your-mailchimp-list-id',
  tagName: 'Refunded',
};

// In your webhook handler (e.g., Express, Fastify, etc.)
app.post('/webhook/stripe', async (req, res) => {
  try {
    const result = await handle(req.body, config);
    res.json({ success: true, ...result });
  } catch (err) {
    console.error(err);
    res.status(500).json({ success: false, error: err.message });
  }
});
```

## Assumptions

- The webhook payload follows Stripe's standard Event structure with `data.object.id` (charge ID) and `data.object.customer` (customer ID).
- The Mailchimp subscriber hash is the Stripe charge ID (per field mapping `charge.id → subscriber.id`). If your Mailchimp subscribers are keyed by email hash, you must pre-compute and store the charge ID as the subscriber's foreign key or use a separate lookup.
- The tag name exists in Mailchimp or will be created on first addition (Mailchimp creates tags automatically when `status: "active"`).
- Mailchimp's `/tags` endpoint supports the `Idempotency-Key` header for safe retries.
- The connector checks existing tags via GET before POST to avoid duplicate additions; the GET response is assumed to contain all tags in a single page (no pagination).
- Webhook signature verification is **not** performed by this connector; implement it upstream (e.g., in your HTTP framework middleware) using `stripe.webhookSigningSecret`.

